326 template <int64_t Val> struct constantint_match {
327   template <typename ITy> bool match(ITy *V) {
328     if (const auto *CI = dyn_cast<ConstantInt>(V)) {
329       const APInt &CIV = CI->getValue();
330       if (Val >= 0)
